177	/* Handle "set_timer" tool call.
178	 *   arguments:
179	 *     duration  (int, required) — seconds from now
180	 *     message   (string, optional) — message to display when timer expires
181	 *   Returns the timer id and remaining seconds.
182	 */
183	
184	static cJSON *handle_set_timer(cJSON *id, cJSON *params)
185	{
186	  cJSON *args = cJSON_GetObjectItem(params, "arguments");
187	  if (args == NULL)
188	    {
189	      cJSON *resp   = reply_result(id);
190	      cJSON *result = cJSON_GetObjectItem(resp, "result");
191	      cJSON_AddItemToObject(result, "content",
192	        make_text_content("Missing arguments"));
193	      cJSON_AddBoolToObject(result, "isError", true);
194	      return resp;
195	    }
196	
197	  cJSON *dur_item = cJSON_GetObjectItem(args, "duration");
198	  if (!cJSON_IsNumber(dur_item))
199	    {
200	      cJSON *resp   = reply_result(id);
201	      cJSON *result = cJSON_GetObjectItem(resp, "result");
202	      cJSON_AddItemToObject(result, "content",
203	        make_text_content("Missing or invalid 'duration' (seconds)"));
204	      cJSON_AddBoolToObject(result, "isError", true);
205	      return resp;
206	    }
207	
208	  int duration = dur_item->valueint;
209	  if (duration <= 0 || duration > 86400)  /* max 24 hours */
210	    {
211	      cJSON *resp   = reply_result(id);
212	      cJSON *result = cJSON_GetObjectItem(resp, "result");
213	      cJSON_AddItemToObject(result, "content",
214	        make_text_content("Duration must be between 1 and 86400 seconds"));
215	      cJSON_AddBoolToObject(result, "isError", true);
216	      return resp;
217	    }
218	
219	  struct timer_s *t = timer_alloc();
220	  if (t == NULL)
221	    {
222	      cJSON *resp   = reply_result(id);
223	      cJSON *result = cJSON_GetObjectItem(resp, "result");
224	      cJSON_AddItemToObject(result, "content",
225	        make_text_content("Too many active timers (max 8)"));
226	      cJSON_AddBoolToObject(result, "isError", true);
227	      return resp;
228	    }
229	
230	  t->end_time = time(NULL) + duration;
231	
232	  cJSON *msg_item = cJSON_GetObjectItem(args, "message");
233	  if (cJSON_IsString(msg_item))
234	    {
235	      strncpy(t->message, msg_item->valuestring,
236	              TIMER_MSG_MAX - 1);
237	      t->message[TIMER_MSG_MAX - 1] = '\0';
238	    }
239	  else
240	    {
241	      snprintf(t->message, sizeof(t->message), "Timer %d", t->id);
242	    }
243	
244	  printf("[mcp] timer %d set: %d seconds, msg=\"%s\"\n",
245	         t->id, duration, t->message);
246	
247	  /* Build success response with timer info. */
248	
249	  {
250	    char text[256];
251	    cJSON *resp   = reply_result(id);
252	    cJSON *result = cJSON_GetObjectItem(resp, "result");
253	
254	    snprintf(text, sizeof(text),
255	             "Timer %d 已设置，%d 秒后到期。消息: %s",
256	             t->id, duration, t->message);
257	    cJSON_AddItemToObject(result, "content", make_text_content(text));
258	    cJSON_AddBoolToObject(result, "isError", false);
259	    return resp;
260	  }
261	}
