694	/* Dispatch one JSON-RPC request object to a handler and return the
695	 * response. Returns NULL for notifications (no id field). */
696	
697	static cJSON *dispatch(cJSON *req)
698	{
699	  cJSON *method = cJSON_GetObjectItem(req, "method");
700	  cJSON *id     = cJSON_GetObjectItem(req, "id");
701	  cJSON *params = cJSON_GetObjectItem(req, "params");
702	  const char *mstr = cJSON_IsString(method) ? method->valuestring : NULL;
703	
704	  if (mstr == NULL)
705	    {
706	      return reply_error(id, -32600, "Missing method");
707	    }
708	
709	  if (strcmp(mstr, "initialize") == 0)
710	    {
711	      return handle_initialize(id);
712	    }
713	
714	  if (strcmp(mstr, "tools/list") == 0)
715	    {
716	      return handle_tools_list(id);
717	    }
718	
719	  if (strcmp(mstr, "tools/call") == 0)
720	    {
721	      return handle_tools_call(id, params ? params : cJSON_CreateObject());
722	    }
723	
724	  /* Notifications (no id) are not answered. */
725	
726	  if (id == NULL)
727	    {
728	      return NULL;
729	    }
730	
731	  {
732	    char msg[80];
733	    snprintf(msg, sizeof(msg), "Method not implemented: %s", mstr);
734	    return reply_error(id, -32601, msg);
735	  }
736	}
