35	/* Wrap a JSON-RPC response in an "mcp" frame and send it to the cloud. */
36	
37	static void mcp_send_response(struct xiaozhi_ws_s *ws,
38	                              const char *session_id,
39	                              cJSON *resp)
40	{
41	  cJSON *frame = cJSON_CreateObject();
42	  cJSON_AddStringToObject(frame, "type", "mcp");
43	  cJSON_AddStringToObject(frame, "session_id", session_id);
44	  cJSON_AddItemToObject(frame, "payload", resp);  /* frame owns resp */
45	
46	  char *j = cJSON_PrintUnformatted(frame);
47	  if (j != NULL)
48	    {
49	      xiaozhi_ws_send_text(ws, j, strlen(j));
50	      free(j);
51	    }
52	
53	  cJSON_Delete(frame);
54	}
55	
56	/* Send a JSON-RPC error response back to the cloud. */
57	
58	static void mcp_send_error(struct xiaozhi_ws_s *ws,
59	                           const char *session_id,
60	                           cJSON *id, int code, const char *message)
61	{
62	  cJSON *resp = cJSON_CreateObject();
63	  cJSON *err  = cJSON_CreateObject();
64	  cJSON_AddStringToObject(resp, "jsonrpc", "2.0");
65	  if (id != NULL)
66	    {
67	      cJSON_AddItemReferenceToObject(resp, "id", id);
68	    }
69	
70	  cJSON_AddItemToObject(resp, "error", err);
71	  cJSON_AddNumberToObject(err, "code", code);
72	  cJSON_AddStringToObject(err, "message", message);
73	
74	  mcp_send_response(ws, session_id, resp);
75	}
